import sys,numpy as np,mujoco
sys.path.insert(0,'/opt/tools'); import rcb_dtb

def qmul(a,b):
 w,x,y,z=a; W,X,Y,Z=b; return np.array([w*W-x*X-y*Y-z*Z,w*X+x*W+y*Z-z*Y,w*Y-x*Z+y*W+z*X,w*Z+x*Y-y*X+z*W])
def qc(q): return q*np.array([1,-1,-1,-1])
def rv(q):
 if q[0]<0:q=-q
 n=np.linalg.norm(q[1:]); return np.zeros(3) if n<1e-10 else q[1:]/n*2*np.arctan2(n,q[0])
def run(pose,close):
 s=rcb_dtb.Session('/app/instance.json'); m,d=s.model,s.data; palm=m.body('palmworld').id; qidx=s._jq[:7]; dof=s._jv[:7]; jp=np.zeros((3,m.nv)); jr=np.zeros((3,m.nv)); q0=d.xquat[palm].copy(); qseed=d.qpos[qidx].copy()
 def ik(pos):
  nonlocal qseed
  q=qseed.copy(); sav=d.qpos.copy()
  for _ in range(30):
   d.qpos[qidx]=q; mujoco.mj_forward(m,d); e=np.r_[pos-d.xpos[palm],rv(qmul(q0,qc(d.xquat[palm])))];
   if np.linalg.norm(e)<.0005:break
   mujoco.mj_jacBody(m,d,jp,jr,palm);J=np.vstack((jp[:,dof],jr[:,dof])); dq=J.T@np.linalg.solve(J@J.T+.002*np.eye(6),e); dq*=min(1,.15/max(1e-9,np.linalg.norm(dq))); q=np.clip(q+dq,s.lower[:7],s.upper[:7])
  d.qpos[:]=sav;mujoco.mj_forward(m,d); qseed=q; return q
 def step(p,hand):
  return s.step(np.r_[ik(p),hand])
 start=d.xpos[palm].copy()
 for i in range(1,91):
  u=i/90;u=u*u*(3-2*u); step(start*(1-u)+pose*u,np.zeros(22))
 for i in range(1,91):
  u=min(i/65,1);u=u*u*(3-2*u);step(pose,close*u)
 for _ in range(30):step(pose,close)
 pre=s.state()['object_pos'].copy(); print('pre lift',pose,'obj',pre,'tips',[d.xpos[m.body('palmleft_'+f+'_DP').id].round(3).tolist() for f in ['thumb','index','middle','ring','pinky']],'ncon',d.ncon)
 for i in range(1,61):
  step(pose+np.array([0,0,.035*i/60]),close)
 post=s.state()['object_pos'].copy(); print('post',post,'delta',post-pre,'dist',s.goal_distance(),'contacts',d.ncon)
 return post-pre
base=np.array([1.,0.,.9,0.,1.1,.85,0.,1.2,.8,.85,0.,1.2,.8,.85,0.,1.2,.8,.12,.8,0.,1.2,.8])
strong=np.array([1.4,0.,1.2,0.,1.4,1.3,0.,1.5,1.15,1.3,0.,1.5,1.15,1.3,0.,1.5,1.15,.2,1.3,0.,1.5,1.15])
for p,c in [(np.array([.096,.214,.633]),base),(np.array([.096,.185,.615]),base),(np.array([.096,.185,.615]),strong),(np.array([.096,.165,.600]),strong)]: run(p,c)
PY
